// buildEnforcer wires the Casbin enforcer against the policy-engine MongoDB.
// POLICY_MONGO_URI unset, or any connection failure, falls back to DenyAll
// (fail-closed) — which only matters for fields carrying @auth/@policy.
func buildEnforcer() policy.Enforcer {
	uri := os.Getenv("POLICY_MONGO_URI")
	if uri == "" {
		log.Printf("⚠  POLICY_MONGO_URI unset — directive-guarded fields will be DENIED (DenyAll)")
		return policy.DenyAll{}
	}
	db := env("POLICY_MONGO_DB", "lms_policy")
	coll := env("POLICY_MONGO_COLLECTION", "casbin_rule")
	ce, err := policy.NewCasbin(context.Background(), uri, db, coll)
	if err != nil {
		log.Printf("⚠  casbin enforcer init failed (%v) — falling back to DenyAll", err)
		return policy.DenyAll{}
	}
	log.Printf("✅ policy: Casbin enforcer on Mongo %s.%s", db, coll)
	return ce
}

